	/** 
	 * jumpstart the process by instantiating2 Routing
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		routingId = RoutingService.getRoutingInstance()
		.createRouting( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		RoutingService.getRoutingInstance()
				.createRouting( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.routingSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Routing : " + successValue.getRoutingId());
							  if (successValue.getRoutingId().equals(routingId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfRoutingList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Routing test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on routing consumed")
					);
			subscriber.routingSubscribe( routingId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Routing : " + successValue.getRoutingId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfRoutingList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on routing for routingId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Routing. 
	 */
	protected Routing read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Routing" );

		Routing entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Routing with primary key" );
		msg.append( routingId );
		
		RoutingFetchOneSummary fetchOneSummary = new RoutingFetchOneSummary( routingId );

		try {
			entity = RoutingService.getRoutingInstance().getRouting( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Routing " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Routing.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Routing." );

		StringBuilder msg = new StringBuilder( "Failed to update a Routing : " );        
		Routing entity = read();
		UpdateRoutingCommand command = generateUpdateCommand();
		command.setRoutingId(entity.getRoutingId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Routing." );

			// for use later on...
			routingId = entity.getRoutingId();

			RoutingService proxy = RoutingService.getRoutingInstance();  

			proxy.updateRouting( command ).get();

			LOGGER.info( "-- Successfully saved Routing - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + routingId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Routing.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Routing." );

		Routing entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Routing with id " + routingId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Routing with id " + routingId );

			throw e;
		}

		try{
			RoutingService.getRoutingInstance().delete( new DeleteRoutingCommand( entity.getRoutingId() ) ).get();
			LOGGER.info( "-- Successfully deleted Routing with id " + routingId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Routing with id " + routingId );

			throw e;
		}
	}

	/**
	 * get all Routings.
	 */
	protected List<Routing> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Routings:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Routing : " );        
		List<Routing> collection  = new ArrayList<>();

		try {
			// call the static get method on the RoutingService
			collection = RoutingService.getRoutingInstance().getAllRouting();
			assertNotNull( collection, "An Empty collection of Routing was incorrectly returned.");
			
			// Now print out the values
			Routing entity = null;            
			Iterator<Routing> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getRoutingId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

